import{_ as t,o as r,c as a,ag as o}from"./chunks/framework.DQQHyi2x.js";const s="/docs/images/operating-model/hierarchy.svg",n="/docs/images/operating-model/factory.svg",i="/docs/images/operating-model/modes.svg",d="/docs/images/operating-model/supervisor-tick.svg",h="/docs/images/operating-model/heartbeat-status.svg",f=JSON.parse('{"title":"Factory operating model","description":"","frontmatter":{},"headers":[],"relativePath":"guide/operating-model.md","filePath":"guide/operating-model.md"}'),l={name:"guide/operating-model.md"};function c(p,e,u,g,m,y){return r(),a("div",null,[...e[0]||(e[0]=[o('<h1 id="factory-operating-model" tabindex="-1">Factory operating model <a class="header-anchor" href="#factory-operating-model" aria-label="Permalink to &quot;Factory operating model&quot;">​</a></h1><p>This page shows who does what when a Albiex Synth City team works on a GitHub backlog. Use it with the <a href="./supervised-factory-playbook.html">Supervised factory playbook</a>: this page explains the model, and the playbook gives the procedures.</p><p>Select a figure to open it at full size. Parts marked <strong>Planned (v3.1)</strong> come from proposal <a href="https://github.com/albiexai/synth-city/issues/506" target="_blank" rel="noreferrer">#506</a>. They are not in Deck 3.0.0. In the figures, green boxes are planned.</p><div class="info custom-block"><p class="custom-block-title">Naming</p><p>This page calls the human role the <strong>Director</strong>. Agent Mail already uses that name. The Deck 3.0.0 UI and API still say <em>operator</em> for the same role, for example the operator token and the operator API. In code, <code>operator</code> remains the name of the Director&#39;s authority interface. A supervisor uses it only under delegation. A later release will call the token the <strong>Director key</strong> in the UI (<a href="https://github.com/albiexai/synth-city/issues/518" target="_blank" rel="noreferrer">#518</a>).</p></div><h2 id="kinds-of-actor" tabindex="-1">Kinds of actor <a class="header-anchor" href="#kinds-of-actor" aria-label="Permalink to &quot;Kinds of actor&quot;">​</a></h2><p>Each actor is one of three kinds.</p><table tabindex="0"><thead><tr><th>Kind</th><th>Actors</th><th>Job</th></tr></thead><tbody><tr><td><strong>Human</strong></td><td>The Director</td><td>Owns the outcome and the backlog. Makes the retained decisions.</td></tr><tr><td><strong>AI agent</strong></td><td>Supervisor, Leader, implementers, verifiers, optional grooming helper</td><td>Work that needs judgment: supervision, planning, implementation and review.</td></tr><tr><td><strong>Non-agent system</strong></td><td>Synth City controller, maintenance script, GitHub</td><td>Work that a rule can do: dispatch, leases, Mail, attention signals, the maintenance operation and the record.</td></tr></tbody></table><p>When a rule can do a job, the job belongs in the controller, not in an agent prompt.</p><h2 id="hierarchy-of-roles" tabindex="-1">Hierarchy of roles <a class="header-anchor" href="#hierarchy-of-roles" aria-label="Permalink to &quot;Hierarchy of roles&quot;">​</a></h2><p><a href="/docs/images/operating-model/hierarchy.svg"><img src="'+s+'" alt="Hierarchy of roles: the Director at the top; the supervisor and the grooming helper as optional staff roles; the Leader; implementers and verifiers; the Synth City controller and GitHub as non-agent systems, not ranks"></a></p><ul><li>The line of command is Director → Leader → implementers and verifiers.</li><li>The supervisor and the grooming helper are <strong>staff roles</strong> beside that line. Both are optional. Without a supervisor, the Leader reports directly to the Director.</li><li>The supervisor uses the Director&#39;s powers only within the recorded delegation. It does not take the Leader&#39;s authority over plans and backlog assessments.</li><li>Each team has one Leader, selected by <code>leader_slot_id</code>. The Director chooses the number of implementers and verifiers. Scope limits such as <code>max_concurrent_dispatched</code> limit concurrent work, not team size.</li><li>The Synth City controller and GitHub are not ranks. The controller enforces the hierarchy with tokens, leases, limits and Mail identity. GitHub holds the backlog and the record.</li><li>An external agent, such as OpenClaw, takes the supervisor role. It is not a second Director.</li></ul><h2 id="the-factory" tabindex="-1">The factory <a class="header-anchor" href="#the-factory" aria-label="Permalink to &quot;The factory&quot;">​</a></h2><p><a href="/docs/images/operating-model/factory.svg"><img src="'+n+'" alt="The factory: the Synth City controller and the team inside the factory boundary; the Director, the supervisor, the grooming helper and GitHub outside it"></a></p><p>The <strong>factory</strong> is the Synth City controller and the AI teams, working together on the Director&#39;s backlog. The Director, the supervisor, the AI helpers and GitHub work with the factory from outside it.</p><p>Test: if the Director must start, stop, upgrade or repair a part, the part is in the factory. The Director starts, stops, upgrades and repairs the Synth City controller and the teams. The supervisor helps the Director do that, from outside.</p><table tabindex="0"><thead><tr><th>Part</th><th>In the factory?</th><th>Reason</th></tr></thead><tbody><tr><td>Supervisor (AI agent)</td><td>No</td><td>It helps the Director start, stop, upgrade and repair the factory, from outside. Its powers come from the Director&#39;s recorded delegation.</td></tr><tr><td>Synth City controller (non-agent)</td><td>Yes</td><td>Maintenance upgrades and repairs it.</td></tr><tr><td>Team (AI agents)</td><td>Yes</td><td>Synth City launches its sessions. The Director chooses the roster.</td></tr><tr><td>GitHub (non-agent)</td><td>No</td><td>It keeps running when the factory stops. It holds the backlog, and the result goes out there.</td></tr><tr><td>Director (human)</td><td>No</td><td>The Director owns the factory and the backlog and keeps the retained decisions.</td></tr><tr><td>Grooming helper (AI agent)</td><td>No</td><td>It is optional. It works for the Director, not for the factory.</td></tr></tbody></table><h3 id="the-director-owns-the-backlog" tabindex="-1">The Director owns the backlog <a class="header-anchor" href="#the-director-owns-the-backlog" aria-label="Permalink to &quot;The Director owns the backlog&quot;">​</a></h3><p>The Director owns and grooms the GitHub backlog:</p><ul><li>Write and order the issues.</li><li>Set the acceptance conditions.</li><li>Apply the dispatch label. The dispatch label is the Director&#39;s &quot;ready&quot; signal.</li></ul><p>An optional AI agent can help. It drafts or splits issues for the Director, and the Director decides. The Leader assesses the groomed backlog and selects the next eligible work. The Leader does not own the backlog.</p><h2 id="two-operating-modes" tabindex="-1">Two operating modes <a class="header-anchor" href="#two-operating-modes" aria-label="Permalink to &quot;Two operating modes&quot;">​</a></h2><p><a href="/docs/images/operating-model/modes.svg"><img src="'+i+'" alt="Two operating modes: in normal running, Synth City flags a problem and the Leader or the Director acts; in factory maintenance, the supervisor prepares a fix, the owners hand off, the maintenance script upgrades the controller, and the supervisor checks the state and resumes"></a></p><p><strong>Normal running.</strong> Synth City code finds problems: stopped attempts, stalled owners, recovery decisions, review or merge requests and HOLD. The Leader acts on backlog work. The Director makes the retained decisions. A supervisor is optional.</p><p><strong>Factory maintenance.</strong> Maintenance is a Synth City feature that the supervisor drives from outside the factory, helping the Director.</p><ul><li>Synth City supplies <code>scripts/factory-maintenance.py</code> and its checks: owner checkpoints through Mail, pause, backup, proof of termination, deploy and retained-state checks.</li><li>The supervisor decides when to run it, prepares the reviewed fix and the request files, runs the operation and resumes the factory.</li><li>Team sessions keep running through the controller restart. The upgrade is refused if a session binding or generation changes.</li><li>A successful upgrade ends as <code>deployed_paused</code>. Resume enables autonomy again and releases the operation&#39;s holds. It does not start any agent again.</li><li>While the controller is down, the Synth City UI is not available. The parent GitHub issue is the only live status surface.</li></ul><p>See the <a href="https://github.com/albiexai/synth-city/blob/master/docs/deploy/factory-maintenance-operations.md" target="_blank" rel="noreferrer">maintenance runbook</a> and the playbook&#39;s <a href="./supervised-factory-playbook.html#_9-stop-safely-for-factory-maintenance">maintenance section</a>.</p><h2 id="why-the-supervisor-runs-outside-the-controller" tabindex="-1">Why the supervisor runs outside the controller <a class="header-anchor" href="#why-the-supervisor-runs-outside-the-controller" aria-label="Permalink to &quot;Why the supervisor runs outside the controller&quot;">​</a></h2><p>The supervisor works on the factory from outside it, and it does not run inside the controller process either.</p><ul><li><strong>It cannot upgrade its own host.</strong> An upgrade stops the controller, proves termination and restarts it. An agent inside the controller stops when the controller stops.</li><li><strong>A watchdog must not fail with the thing it watches.</strong> If the controller stalls or crashes, an internal supervisor stops too, and nobody sees the failure.</li><li><strong>A controller that repairs itself is unsafe.</strong> An internal agent with permission to change and deploy Synth City makes the safety model much harder to understand.</li></ul><table tabindex="0"><thead><tr><th>Duty</th><th>Owner</th><th>Kind</th></tr></thead><tbody><tr><td>Own and groom the backlog</td><td>Director, optionally helped by an agent</td><td>Human</td></tr><tr><td>Detect stalls, stopped attempts, holds and required decisions</td><td>Synth City controller</td><td>Non-agent</td></tr><tr><td>Assess the groomed backlog, approve plans, select the next eligible work</td><td>Team Leader</td><td>AI agent</td></tr><tr><td>Repair, upgrade and roll back the factory</td><td>Supervisor, with the maintenance script</td><td>AI agent and non-agent</td></tr><tr><td>Retained decisions: publication, budgets, models, security HOLD</td><td>Director</td><td>Human</td></tr></tbody></table><h2 id="one-campaign-start-to-finish" tabindex="-1">One campaign, start to finish <a class="header-anchor" href="#one-campaign-start-to-finish" aria-label="Permalink to &quot;One campaign, start to finish&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Actor</th><th>Groom</th><th>Prepare</th><th>Run</th><th>Decision</th><th>Maintenance</th><th>Finish</th></tr></thead><tbody><tr><td><strong>Director</strong> (human)</td><td>Write and order issues; apply the dispatch label</td><td>Write the outcome and delegation; authorize the start</td><td>Groom at any time; read the summary</td><td>Approve or decide on GitHub</td><td>Only for a security HOLD</td><td>Approve publication</td></tr><tr><td><strong>Supervisor</strong> (AI agent, optional)</td><td>Draft issues for the Director</td><td>Run startup checks</td><td>Fix routine blockers within delegation</td><td>Prepare the exact request and evidence</td><td>Fix, hand off, run the reviewed upgrade</td><td>Reconcile records; disable dispatch</td></tr><tr><td><strong>Synth City controller</strong> (non-agent)</td><td>Poll labelled issues</td><td>Store scopes, leases and Mail identity</td><td>Dispatch; bound attempts; show signals</td><td>List the human action</td><td>Record the operation; preserve authority and leases</td><td>Show the result</td></tr><tr><td><strong>Leader and team</strong> (AI agents)</td><td>Optional readiness assessment</td><td>Mail canary</td><td>Assess, plan, implement, verify</td><td>Independent work continues</td><td>Owner checkpoint, then hold</td><td>Close issues</td></tr><tr><td><strong>GitHub</strong> (non-agent)</td><td>The Director&#39;s backlog</td><td>Parent issue and backlog</td><td>PRs and required CI</td><td>Exact instructions in the issue</td><td>Only live status surface</td><td>Final record</td></tr></tbody></table><h2 id="supervisor-heartbeat-—-planned-v3-1" tabindex="-1">Supervisor heartbeat — Planned (v3.1) <a class="header-anchor" href="#supervisor-heartbeat-—-planned-v3-1" aria-label="Permalink to &quot;Supervisor heartbeat — Planned (v3.1)&quot;">​</a></h2><p><a href="/docs/images/operating-model/supervisor-tick.svg"><img src="'+d+'" alt="Supervisor tick: read, act if delegated, publish if changed, check in" width="48%"></a><a href="/docs/images/operating-model/heartbeat-status.svg"><img src="'+h+`" alt="The controller derives Healthy, Late or Absent from the last check-in and the clock" width="48%"></a></p><p>The supervisor keeps no state between ticks. It reads Synth City and GitHub again on each tick, so a harness exit or reboot loses nothing. Replay safety comes from the controller&#39;s existing <code>replay_key</code> and <code>operation_id</code> records.</p><p>At the end of each tick, the supervisor promises its next check (<code>next_check_at</code>). The controller compares that promise with the clock. The supervisor never reports its own health.</p><table tabindex="0"><thead><tr><th>Status</th><th>Meaning</th></tr></thead><tbody><tr><td>None</td><td>No supervisor is registered. This is not an error.</td></tr><tr><td>Healthy</td><td>The promised check has not passed.</td></tr><tr><td>Late</td><td>The check is overdue. Work can still run.</td></tr><tr><td>Absent</td><td>No check-in, or the check is overdue past the threshold.</td></tr></tbody></table><h2 id="director-s-summary-—-planned-v3-1" tabindex="-1">Director&#39;s summary — Planned (v3.1) <a class="header-anchor" href="#director-s-summary-—-planned-v3-1" aria-label="Permalink to &quot;Director&#39;s summary — Planned (v3.1)&quot;">​</a></h2><p>One summary at the top of the Overview answers three questions: Do I need to act? Is anyone watching? What work remains? Most lines collect data that Deck 3.0.0 already has. The supervisor line and the team total for remaining work are new. See <a href="https://github.com/albiexai/synth-city/issues/506" target="_blank" rel="noreferrer">#506</a> and <a href="https://github.com/albiexai/synth-city/issues/508" target="_blank" rel="noreferrer">#508</a>.</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Publish the next release                      Parent issue: #NNN</span></span>
<span class="line"><span>Outcome:     Release tagged, website live, final record posted</span></span>
<span class="line"><span>Supervisor:  Healthy. Checked 2 minutes ago. Next check in 8 minutes.</span></span>
<span class="line"><span>Attention:   None open</span></span>
<span class="line"><span>Remaining:   Publish the release and the website. Estimate: under 1 active hour.</span></span>
<span class="line"><span>Next actor:  You</span></span>
<span class="line"><span>Your action: Review the previews and approve publication on #NNN at SHA &lt;sha&gt;.</span></span></code></pre></div>`,40)])])}const k=t(l,[["render",c]]);export{f as __pageData,k as default};
